import{_ as i,o as a,c as e,a2 as r}from"./chunks/framework.DnrXFDHb.js";const d=JSON.parse('{"title":"附录 C：术语表","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/appendix-c-glossary.md","filePath":"chapters/appendix-c-glossary.md"}'),t={name:"chapters/appendix-c-glossary.md"};function o(n,l,s,p,u,g){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="附录-c-术语表" tabindex="-1">附录 C：术语表 <a class="header-anchor" href="#附录-c-术语表" aria-label="Permalink to &quot;附录 C：术语表&quot;">​</a></h1><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><p><strong>Checkpoint</strong></p><ul><li>训练过程中保存的模型状态，包含模型权重、优化器状态、训练进度等</li><li>可用于恢复训练或推理部署</li></ul><p><strong>Contrastive Loss</strong></p><ul><li>对比损失，用于嵌入学习</li><li>通过拉近正样本、推开负样本来学习表示</li></ul><p><strong>CrossEntropy Loss</strong></p><ul><li>交叉熵损失，语言模型的标准损失函数</li><li>衡量预测分布与真实分布的差异</li></ul><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><p><strong>DeepSpeed</strong></p><ul><li>微软开源的分布式训练库</li><li>提供 ZeRO 优化器，通过切分优化器状态、梯度和参数减少显存占用</li></ul><p><strong>DPO (Direct Preference Optimization)</strong></p><ul><li>直接偏好优化，直接从偏好数据训练模型</li><li>无需训练奖励模型，训练更稳定</li></ul><p><strong>DP (Data Parallelism)</strong></p><ul><li>数据并行，每个 GPU 处理不同的数据批次</li><li>最常见的分布式训练策略</li></ul><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><p><strong>Embedding</strong></p><ul><li>嵌入，将离散的 token 映射为连续的向量表示</li><li>用于语义相似度、检索等任务</li></ul><p><strong>Epoch</strong></p><ul><li>训练轮数，整个数据集被遍历一次的完整过程</li></ul><h2 id="f" tabindex="-1">F <a class="header-anchor" href="#f" aria-label="Permalink to &quot;F&quot;">​</a></h2><p><strong>FSDP (Fully Sharded Data Parallel)</strong></p><ul><li>PyTorch 原生的分布式训练方案</li><li>类似于 DeepSpeed ZeRO-3</li></ul><p><strong>Full Fine-tuning</strong></p><ul><li>全参数微调，更新模型的所有参数</li><li>效果最好，但显存占用大</li></ul><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><p><strong>GaLore (Gradient Low-Rank Projection)</strong></p><ul><li>梯度低秩投影优化器</li><li>通过低秩近似减少优化器状态的显存占用</li></ul><p><strong>GKD (Generalized Knowledge Distillation)</strong></p><ul><li>广义知识蒸馏</li><li>通过 JSD 损失让学生模型学习教师模型的分布</li></ul><p><strong>GRPO (Group Relative Policy Optimization)</strong></p><ul><li>组相对策略优化</li><li>在每个 prompt 的多个响应内计算相对优势，无需奖励模型</li></ul><p><strong>GPTQ</strong></p><ul><li>基于 GPU 的 Post-Training 量化方法</li><li>4-bit 量化，压缩模型大小</li></ul><h2 id="k" tabindex="-1">K <a class="header-anchor" href="#k" aria-label="Permalink to &quot;K&quot;">​</a></h2><p><strong>KL Divergence</strong></p><ul><li>KL 散度，衡量两个概率分布的差异</li><li>在 RLHF 中用于约束策略更新幅度</li></ul><p><strong>KTO (Kahneman-Tversky Optimization)</strong></p><ul><li>基于前景理论的优化方法</li><li>只需要二元反馈（好/坏），不需要成对偏好数据</li></ul><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><p><strong>LoRA (Low-Rank Adaptation)</strong></p><ul><li>低秩适配，通过低秩矩阵分解实现参数高效微调</li><li>只训练少量参数，显存占用小</li></ul><p><strong>LoRA+</strong></p><ul><li>LoRA 的改进版本</li><li>为 A 和 B 矩阵使用不同的学习率</li></ul><p><strong>Loss Scale</strong></p><ul><li>损失缩放，控制哪些 token 参与损失计算</li><li>用于 Agent 训练等场景</li></ul><h2 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h2><p><strong>Megatron-LM</strong></p><ul><li>NVIDIA 开发的大规模语言模型训练框架</li><li>支持张量并行、流水线并行、序列并行</li></ul><p><strong>MRL (Matryoshka Representation Learning)</strong></p><ul><li>嵌套表示学习</li><li>在不同维度截断上计算损失，支持灵活的嵌入维度</li></ul><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><p><strong>ORPO (Odds Ratio Preference Optimization)</strong></p><ul><li>优势比偏好优化</li><li>无需参考模型，单阶段完成 SFT 和对齐</li></ul><p><strong>ORM (Outcome Reward Model)</strong></p><ul><li>结果奖励模型</li><li>基于最终结果给出奖励分数</li></ul><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><p><strong>Packing</strong></p><ul><li>将多个短样本拼接为一个长序列</li><li>提高训练效率，减少 padding 开销</li></ul><p><strong>PPO (Proximal Policy Optimization)</strong></p><ul><li>近端策略优化，经典的强化学习算法</li><li>需要策略模型、参考模型、奖励模型、价值模型</li></ul><p><strong>PP (Pipeline Parallelism)</strong></p><ul><li>流水线并行，将模型层切分到多个 GPU</li><li>适合超大规模模型</li></ul><p><strong>PRM (Process Reward Model)</strong></p><ul><li>过程奖励模型</li><li>基于推理过程的每一步给出奖励分数</li></ul><h2 id="q" tabindex="-1">Q <a class="header-anchor" href="#q" aria-label="Permalink to &quot;Q&quot;">​</a></h2><p><strong>QLoRA</strong></p><ul><li>量化 LoRA</li><li>在 4-bit 量化模型上使用 LoRA 微调</li><li>显存占用最小</li></ul><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><p><strong>Reward Model</strong></p><ul><li>奖励模型，将人类偏好建模为标量分数</li><li>用于 PPO 训练</li></ul><p><strong>RLHF (Reinforcement Learning from Human Feedback)</strong></p><ul><li>基于人类反馈的强化学习</li><li>通过奖励模型和 PPO 算法对齐模型行为</li></ul><p><strong>Reranker</strong></p><ul><li>重排模型，对候选文档进行排序</li><li>用于检索增强生成（RAG）</li></ul><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><p><strong>SFT (Supervised Fine-Tuning)</strong></p><ul><li>监督微调</li><li>使用标注数据训练模型</li></ul><p><strong>SimPO (Simple Preference Optimization)</strong></p><ul><li>简化版 CPO</li><li>使用平均 log 概率，无需参考模型</li></ul><p><strong>Sequence Parallel</strong></p><ul><li>序列并行，将长序列切分到多个 GPU</li><li>适合超长文本训练</li></ul><p><strong>SwanLab</strong></p><ul><li>实验追踪平台</li><li>记录训练指标、超参数、模型性能</li></ul><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><p><strong>Template</strong></p><ul><li>模板系统，统一不同模型的对话格式</li><li>处理 system prompt、user query、assistant response</li></ul><p><strong>Tensor Parallel</strong></p><ul><li>张量并行，将模型参数切分到多个 GPU</li><li>适合大规模模型的单层计算</li></ul><p><strong>Tokenizer</strong></p><ul><li>分词器，将文本转换为 token ID</li><li>不同模型使用不同的分词策略</li></ul><p><strong>TRL (Transformer Reinforcement Learning)</strong></p><ul><li>HuggingFace 的强化学习训练库</li><li>提供 DPO、PPO、GRPO 等算法的实现</li></ul><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><p><strong>WandB (Weights &amp; Biases)</strong></p><ul><li>实验追踪平台</li><li>记录训练指标、可视化训练过程</li></ul><h2 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h2><p><strong>ZeRO (Zero Redundancy Optimizer)</strong></p><ul><li>DeepSpeed 的核心优化技术</li><li>通过切分优化器状态、梯度和参数减少显存占用</li><li>ZeRO-1：切分优化器状态</li><li>ZeRO-2：切分优化器状态和梯度</li><li>ZeRO-3：切分优化器状态、梯度和参数</li></ul>',99)])])}const c=i(t,[["render",o]]);export{d as __pageData,c as default};
